import React from 'react'
import './styles/DataCard.scss'

const DataCard = ({ data }) => {
    return (
        <div className='group-card'>
            {Object.keys(data).map(key => (
                <p key={key}><strong>{key}:</strong> {data[key]}</p>
            ))}
        </div>
    )
}

export default DataCard
